def test_las_demas_funciones_incluidas_siguen_sin_poder_taparse():
    for nombre in ["texto", "largo", "consultar_ia", "simular_ia", "mostrar"]:
        assert f"'{nombre}' es una función incluida de Mate" in falla(f"sea {nombre} = 3").mensaje
