def test_leer_tabla_dice_donde_busco_el_archivo_que_no_esta(tmp_path, capsys):
    (tmp_path / "precio.csv").write_text("a;b\n1;2\n", encoding="utf-8")
    codigo, _, err = por_main(tmp_path, capsys, 'sea t = leer_tabla("precios.csv")')
