    dado = mate.preguntar_al_programa("m.mate", "hola", {}, entregar_lo_enviado=True)
    assert dado["respuesta"] == "Depósito listo\nVentas: Decime qué querés"
    assert [viaje[0] for viaje in dado["viajes"]] == ["Consulta", "Respuesta"]
