    assert dicho[2].startswith("Ventas: Anotado: 2 x Tomate triturado")
    assert dicho[3].startswith("Ventas: Anotado: 3 x Galletitas")
    assert dicho[4].startswith("Ventas: Anotado: 3 x Galletitas")
