def test_el_manual_dice_lo_que_cambio_con_la_revision_externa():
    leeme = " ".join((RAIZ / "README.md").read_text(encoding="utf-8").split())
    equipo = leeme.split("### Un equipo propio: `nuevo equipo`")[1].split(" ### ")[0]
